import {literatureKey,readingStates,scopes,validatePaper,selectLiterature,mergeLiteratureBackup,markOpened} from './literature-model.mjs';
import {list,write,projects} from './state.mjs';
import {esc,icon,empty,formatDate,download} from './ui.mjs';
const $=s=>document.querySelector(s);
let filters={status:'all',project:'all',tag:'all',query:'',sort:'added'};
const papers=()=>list(literatureKey);
const projectName=id=>projects().find(p=>p.id===id)?.name||'未归入项目';
const readerUrl=p=>'#literature/'+encodeURIComponent(p.id);
const stateLabel=p=>readingStates.find(s=>s[0]===p.status)?.[1]||'待读';
function persist(p,notify){try{const rows=papers(),i=rows.findIndex(r=>r.id===p.id);if(i<0){if(rows.length>=200){notify('文献库最多保存 200 篇，请先导出备份。');return false;}rows.unshift(p);}else rows[i]=p;write(literatureKey,rows);return true;}catch{notify('保存失败，请先导出备份并检查浏览器空间。');return false;}}
const heading=(title,desc,actions='')=>`<div class="hub-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="hub-heading-actions">${actions}</div></div>`;
const noteRows=(rows)=>rows.flatMap(p=>p.notes.map(n=>({...n,paper:p}))).sort((a,b)=>(Date.parse(b.updatedAt)||0)-(Date.parse(a.updatedAt)||0));
function row(p){return `<tr><td><div class="lit-name"><span class="hub-row-icon">${icon('file',19)}</span><div><a href="${readerUrl(p)}">${esc(p.title)}</a><small>${esc(p.authors||'作者未填写')} · ${esc(p.year||'年份未填写')}</small><div class="lit-tags"><span>${esc(projectName(p.projectId))}</span>${p.tags.slice(0,2).map(t=>`<span>${esc(t)}</span>`).join('')}</div></div></div></td><td><span class="lit-scope ${p.scope}">${scopes[p.scope]||'仅元数据'}</span></td><td><span class="lit-state ${p.status}"><i></i>${stateLabel(p)}</span></td><td><div class="lit-actions"><a href="${readerUrl(p)}">${p.scope==='metadata'?'查看信息':p.status==='reading'?'继续阅读':p.scope==='abstract'?'查看摘要':'开始阅读'}</a><button data-lit-edit="${esc(p.id)}" aria-label="编辑文献信息：${esc(p.title)}">⋯</button></div></td></tr>`;}
function sidebars(rows){const recent=rows.filter(p=>p.lastReadAt).sort((a,b)=>Date.parse(b.lastReadAt)-Date.parse(a.lastReadAt)).slice(0,3),notes=noteRows(rows).slice(0,3);return `<section class="card lit-side-card"><h2>最近阅读</h2>${recent.map(p=>`<a class="lit-side-row" href="${readerUrl(p)}">${icon('book',18)}<span><b>${esc(p.title)}</b><small>最近打开 · ${formatDate(p.lastReadAt)}</small></span>${icon('arrow',13)}</a>`).join('')||'<p class="lit-side-empty">打开文献后，在这里继续阅读。不会自动标记已读。</p>'}</section><section class="card lit-side-card"><h2>最近笔记</h2>${notes.map(n=>`<a class="lit-side-row" href="${readerUrl(n.paper)}?tab=notes">${icon('pen',18)}<span><b>${esc(n.text.slice(0,70))}</b><small>${esc(n.paper.title)} · ${formatDate(n.updatedAt)}</small></span></a>`).join('')||'<p class="lit-side-empty">阅读时保存自己的思考，笔记会关联到文献。</p>'}</section><section class="card lit-side-card lit-scope-help"><h2>来源与材料范围</h2><p><b>已有正文</b>：查看已导入的文本</p><p><b>仅摘要</b>：只基于摘要阅读</p><p><b>仅元数据</b>：标题、作者等信息</p><small>正文来自用户输入或本地解析，不保证原文完整。DOI 与链接尚未联网核验。</small></section>`;}
export function mountLiterature({modal,notify}){const rows=papers(),tags=[...new Set(rows.flatMap(p=>p.tags))];$('.dashboard').innerHTML=`${heading('文献与研读','收集文献，记录思考，让每一次阅读服务于你的研究。',`<button class="btn primary" data-lit-add>${icon('plus',16)} 添加文献</button><button class="btn secondary" data-lit-import>${icon('upload',16)} 导入文献</button>`)}<div class="lit-shortcuts">${[['search','文献检索','发现相关研究','在线检索待接入'],['book','文献研读','阅读正文与记录笔记','本地阅读'],['file','文献综述','对照文献，整理结构','框架整理'],['pen','学术翻译','核对原文与译文','AI 待接入']].map(([ico,title,desc,status],i)=>`<button data-lit-tool="${i}">${icon(ico,24)}<span><b>${title}</b><small>${desc}</small><em>${status}</em></span></button>`).join('')}</div><div class="lit-layout"><section class="card lit-library"><header><h2>我的文献库 <small>${rows.length} 篇</small></h2><div class="hub-tabs lit-tabs" role="group" aria-label="阅读状态">${readingStates.map(([id,name])=>`<button data-lit-status="${id}" class="${filters.status===id?'active':''}" aria-pressed="${filters.status===id}">${name} <span>${id==='all'?rows.length:rows.filter(p=>p.status===id).length}</span></button>`).join('')}</div></header><div class="lit-toolbar"><label class="asset-search">${icon('search',16)}<input id="lit-query" aria-label="搜索文献" value="${esc(filters.query)}" placeholder="搜索标题、作者或 DOI"></label><select id="lit-project" aria-label="文献项目"><option value="all">所有项目</option><option value="none" ${filters.project==='none'?'selected':''}>未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${filters.project===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select id="lit-tag" aria-label="文献标签"><option value="all">全部标签</option>${tags.map(t=>`<option value="${esc(t)}" ${filters.tag===t?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="lit-sort" aria-label="文献排序">${[['added','最近添加'],['read','最近打开'],['title','标题排序']].map(([v,n])=>`<option value="${v}" ${filters.sort===v?'selected':''}>${n}</option>`).join('')}</select></div><table class="lit-table"><thead><tr><th scope="col">文献信息</th><th scope="col">材料范围</th><th scope="col">阅读状态</th><th scope="col">操作</th></tr></thead><tbody id="lit-rows"></tbody></table><footer><span id="lit-count"></span> · 阅读状态由你标记</footer></section><aside class="lit-side">${sidebars(rows)}</aside></div><div class="asset-backup">${icon('shield',22)}<div><b>本地文献，请及时备份</b><p>当前内容保存在浏览器；AI 与在线检索尚未接入。</p></div><button class="btn secondary" data-lit-backup>导出文献备份</button></div>`;
const update=()=>{const chosen=selectLiterature(rows,filters,projects());$('#lit-count').textContent=`共 ${chosen.length} 篇文献`;$('#lit-rows').innerHTML=chosen.map(row).join('')||`<tr><td colspan="4"><div class="asset-empty">${icon('book',32)}<h3>${rows.length?'没有匹配的文献':'添加第一篇文献，开始整理研究资料'}</h3><p>${rows.length?'尝试调整关键词、项目或标签。':'导入正文，或手动记录标题、作者与来源。'}</p><button class="btn ${rows.length?'secondary':'primary'}" ${rows.length?'data-lit-reset':'data-lit-add'}>${rows.length?'清除筛选':'添加文献'}</button></div></td></tr>`;document.querySelectorAll('[data-lit-status]').forEach(b=>{b.classList.toggle('active',b.dataset.litStatus===filters.status);b.setAttribute('aria-pressed',b.dataset.litStatus===filters.status);});};update();$('#lit-query').addEventListener('input',e=>{filters.query=e.target.value;update();});for(const [id,key] of [['lit-project','project'],['lit-tag','tag'],['lit-sort','sort']])$('#'+id).addEventListener('change',e=>{filters[key]=e.target.value;update();});$('.dashboard').addEventListener('click',e=>{const status=e.target.closest('[data-lit-status]');if(status){filters.status=status.dataset.litStatus;update();}if(e.target.closest('[data-lit-reset]')){filters={status:'all',project:'all',tag:'all',query:'',sort:'added'};mountLiterature({modal,notify});}} ,{signal:pageSignal()});bindActions({modal,notify});}
let pageController;
function pageSignal(){pageController?.abort();pageController=new AbortController();return pageController.signal;}
function bindActions({modal,notify}){const root=$('.dashboard');root.addEventListener('click',e=>{if(e.target.closest('[data-lit-add]'))paperForm(null,{modal,notify});if(e.target.closest('[data-lit-import]'))paperForm(null,{modal,notify},true);const edit=e.target.closest('[data-lit-edit]');if(edit)paperForm(papers().find(p=>p.id===edit.dataset.litEdit),{modal,notify});if(e.target.closest('[data-lit-backup]')){download('PaperKnow-文献备份.json',JSON.stringify({format:'paperknow-literature-backup',version:1,exportedAt:new Date().toISOString(),papers:papers()},null,2),'application/json');notify('已发起文献备份下载，请确认文件已保存。');}const tool=e.target.closest('[data-lit-tool]');if(tool){const type=Number(tool.dataset.litTool);if(type===1){const p=papers().filter(p=>p.scope!=='metadata').sort((a,b)=>(Date.parse(b.lastReadAt)||0)-(Date.parse(a.lastReadAt)||0))[0];if(p)location.hash=readerUrl(p);else paperForm(null,{modal,notify},true);}else if(type===2)reviewComparison({modal,notify});else if(type===3)openLiteratureTranslation({modal,notify});else modal(type===0?'文献检索':'学术翻译',`<p class="hub-description">${type===0?'在线学术检索尚未接入。可以先添加已获取的文献和来源信息，在文献库内搜索。':'在线翻译模型尚未接入。当前可阅读导入的原文并手动记录译文笔记。'}</p><a class="btn secondary" href="#category/literature">返回文献库</a>`);}} ,{signal:pageController.signal});}
function paperForm(existing,{modal,notify},importMode=false){let text=existing?.text||'',fileName=existing?.fileName||'',warnings=existing?.warnings||[],busy=false;modal(existing?'编辑文献信息':importMode?'导入文献':'添加文献',`<form id="lit-form" class="hub-form"><p class="hub-footnote">手动录入，或导入一份 DOCX / PDF / TXT。备份恢复支持 PaperKnow 文献 JSON；不自动检索或下载全文。</p><label for="lit-upload" class="lit-upload">${icon('upload',20)} ${importMode?'选择文档或文献备份':'导入正文（可选）'}<input id="lit-upload" type="file" accept=".docx,.pdf,.txt,.json"></label><p id="lit-parse-status" role="status"></p><label for="lit-title">文献标题 *</label><input id="lit-title" required maxlength="300" value="${esc(existing?.title||'')}"><div class="hub-form-row"><div><label for="lit-authors">作者</label><input id="lit-authors" maxlength="1000" value="${esc(existing?.authors||'')}" placeholder="多位作者可用顿号分隔"></div><div><label for="lit-year">年份</label><input id="lit-year" pattern="[0-9]{4}" maxlength="4" value="${esc(existing?.year||'')}" placeholder="例如：2025"></div></div><label for="lit-association">所属项目</label><select id="lit-association"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${p.id===existing?.projectId?'selected':''}>${esc(p.name)}</option>`).join('')}</select><label for="lit-tags-input">标签（用逗号分隔）</label><input id="lit-tags-input" maxlength="500" value="${esc(existing?.tags?.join('，')||'')}" placeholder="例如：课堂反馈，教育研究"><div class="hub-form-row"><div><label for="lit-doi">DOI（可选）</label><input id="lit-doi" maxlength="300" value="${esc(existing?.doi||'')}" placeholder="10.1234/example"></div><div><label for="lit-url">来源 URL（可选）</label><input id="lit-url" type="url" maxlength="2000" value="${esc(existing?.url||'')}" placeholder="https://…"></div></div><div class="hub-form-row"><div><label for="lit-scope-input">材料范围</label><select id="lit-scope-input">${Object.entries(scopes).map(([v,n])=>`<option value="${v}" ${v===(existing?.scope||'metadata')?'selected':''}>${n}</option>`).join('')}</select></div><div><label for="lit-state-input">阅读状态</label><select id="lit-state-input">${readingStates.slice(1).map(([v,n])=>`<option value="${v}" ${v===(existing?.status||'unread')?'selected':''}>${n}</option>`).join('')}</select></div></div><label for="lit-text-input">正文 / 摘要（最多 200,000 字符）</label><textarea id="lit-text-input" rows="6" maxlength="200000" placeholder="粘贴有权使用的正文或摘要；仅元数据模式不保存此栏文本。">${esc(text)}</textarea><p class="hub-footnote">文件仅提取文本，不保存原始 PDF / Word。扫描 PDF 不支持 OCR。来源信息由你填写，尚未联网核验。</p><p id="lit-error" class="hub-error" role="alert"></p><button class="btn primary" id="lit-submit" type="submit">${existing?'保存修改':'加入文献库'}</button></form>`);const form=$('#lit-form');$('#lit-upload').addEventListener('change',async e=>{const file=e.target.files[0];if(!file||busy)return;if(file.size>50*1024*1024){$('#lit-error').textContent='文件不可超过 50MB。';return;}busy=true;$('#lit-submit').disabled=true;$('#lit-parse-status').textContent='正在本地读取…';try{if(/\.json$/i.test(file.name)){if(file.size>10*1024*1024)throw Error('文献备份不可超过 10MB。');const backup=JSON.parse(await file.text());if($('#lit-form')!==form)return;const result=mergeLiteratureBackup(papers(),backup);write(literatureKey,result.papers);$('#workspace-dialog').close();mountLiterature({modal,notify});notify(`恢复 ${result.added} 篇；${result.skipped} 篇已有记录保留原内容。`);return;}const {extractFile}=await import('/precheck/assets/parsers.js');const parsed=await extractFile(file);if($('#lit-form')!==form)return;if(!parsed.text.trim())throw Error('未提取到正文，扫描件暂不支持 OCR。');if(parsed.text.length>200000)throw Error('正文超过 200,000 字符，请按章节导入。');text=parsed.text;fileName=file.name;warnings=parsed.warnings;$('#lit-text-input').value=text;$('#lit-scope-input').value='full';if(!$('#lit-title').value)$('#lit-title').value=file.name.replace(/\.[^.]+$/,'');$('#lit-parse-status').textContent=`${fileName} · 已提取 ${text.length.toLocaleString('zh-CN')} 字符${warnings.length?' · '+warnings.slice(0,2).join('；'):''}`;$('#lit-error').textContent='';}catch(err){if($('#lit-form')===form)$('#lit-error').textContent=err.message||'导入失败，请检查文件。';}finally{busy=false;if($('#lit-form')===form){$('#lit-submit').disabled=false;$('#lit-upload').value='';}}});form.addEventListener('submit',e=>{e.preventDefault();if(busy)return;try{const now=new Date().toISOString();const p=validatePaper({...existing,id:existing?.id||crypto.randomUUID(),createdAt:existing?.createdAt||now,updatedAt:now,title:$('#lit-title').value,authors:$('#lit-authors').value,year:$('#lit-year').value,doi:$('#lit-doi').value,url:$('#lit-url').value,tags:$('#lit-tags-input').value,projectId:$('#lit-association').value,scope:$('#lit-scope-input').value,status:$('#lit-state-input').value,text:$('#lit-text-input').value,fileName,warnings,notes:existing?.notes||[]});if(existing?.text&&p.scope==='metadata'&&!window.confirm('切换为仅元数据会移除已保存的正文，笔记保留。确认继续？'))return;if(persist(p,notify)){$('#workspace-dialog').close();mountLiterature({modal,notify});notify('文献已保存到当前浏览器。');}}catch(err){$('#lit-error').textContent=err.message;}});}
export function mountLiteratureReader(id,{modal,notify},tab='text'){try{id=decodeURIComponent(id);}catch{}let paper=papers().find(p=>p.id===id);if(!paper){$('.dashboard').innerHTML=heading('文献不存在','当前浏览器没有这条文献记录。')+empty('返回文献库查看。','#category/literature');return;}if(paper.scope!=='metadata'){const opened=markOpened(paper);if(persist(opened,notify))paper=opened;}
$('.dashboard').innerHTML=`${heading(esc(paper.title),`${esc(paper.authors||'作者未填写')} · ${esc(paper.year||'年份未填写')} · ${esc(projectName(paper.projectId))}`,`<a class="btn secondary" href="#category/literature">返回文献库</a><button class="btn secondary" data-lit-edit="${esc(paper.id)}">编辑信息</button>`)}<div class="lit-reader-meta"><span class="lit-scope ${paper.scope}">${scopes[paper.scope]}</span><label for="reader-state">阅读状态</label><select id="reader-state">${readingStates.slice(1).map(([v,n])=>`<option value="${v}" ${v===paper.status?'selected':''}>${n}</option>`).join('')}</select><span>状态由你标记 · 不自动判断已读</span></div><div class="lit-reading-layout"><section class="card lit-reading-main"><div class="hub-tabs" aria-label="阅读视图"><button data-read-tab="text" class="${tab==='text'?'active':''}">${paper.scope==='abstract'?'摘要':paper.scope==='metadata'?'来源信息':'导入正文'}</button><button data-read-tab="notes" class="${tab==='notes'?'active':''}">我的笔记 ${paper.notes.length}</button></div><section id="reader-text-pane" ${tab==='notes'?'hidden':''}><div class="lit-source-info"><b>来源信息（未联网核验）</b><p>DOI：${paper.doi?`<a href="https://doi.org/${encodeURI(paper.doi)}" target="_blank" rel="noopener noreferrer">${esc(paper.doi)}</a>`:'未提供'}<br>URL：${paper.url?`<a href="${esc(paper.url)}" target="_blank" rel="noopener noreferrer">${esc(paper.url)}</a>`:'未提供'}<br>文件：${esc(paper.fileName||'手动录入')}</p></div>${paper.warnings.length?`<p class="lit-read-notice">解析提醒：${esc(paper.warnings.join('；'))}</p>`:''}<p class="lit-read-notice">${paper.scope==='metadata'?'当前仅有元数据，没有正文可供研读。':paper.scope==='abstract'?'当前仅阅读用户提供的摘要，不代表已获取全文。':'以下为用户输入或文件提取的正文，可能缺少图表、公式和页码。'}</p><article class="lit-read-text">${esc(paper.text||'可通过编辑信息补充正文或摘要。')}</article></section><section id="reader-notes-pane" ${tab!=='notes'?'hidden':''}><h2>我的笔记</h2><div id="reader-notes"></div></section></section><aside class="card lit-note-editor"><h2>记录研究笔记</h2><p>保存自己的理解、问题或手动译文，关联到当前文献。</p><form class="hub-form" id="lit-note-form"><label for="note-location">原文定位（可选）</label><input id="note-location" maxlength="300" placeholder="例如：研究方法段；请自行核对页码"><label for="note-text">笔记内容 *</label><textarea id="note-text" required maxlength="5000" rows="10" placeholder="记录结论、方法、局限或待核对的问题…"></textarea><button class="btn primary" type="submit">保存笔记</button><button class="btn secondary" type="button" id="note-cancel" hidden>取消编辑</button><p id="note-status" role="status"></p></form><div class="lit-note-boundary">AI 研读与翻译尚未接入。笔记由你填写，不自动生成结论或引用。</div><button class="btn secondary" id="note-export">导出笔记 TXT</button></aside></div>`;
let editingId=null;const renderNotes=()=>{$('#reader-notes').innerHTML=paper.notes.map(n=>`<section class="lit-note"><div><small>${esc(n.location||'未填写原文定位')} · ${formatDate(n.updatedAt)}</small><button data-edit-note="${esc(n.id)}">编辑</button></div><p>${esc(n.text)}</p></section>`).join('')||empty('还没有笔记，可在右侧记录自己的思考。');};renderNotes();const signal=pageSignal();$('.dashboard').addEventListener('click',e=>{const t=e.target.closest('[data-read-tab]');if(t){const notes=t.dataset.readTab==='notes';$('#reader-text-pane').hidden=notes;$('#reader-notes-pane').hidden=!notes;document.querySelectorAll('[data-read-tab]').forEach(b=>b.classList.toggle('active',b===t));}const edit=e.target.closest('[data-edit-note]');if(edit){const n=paper.notes.find(n=>n.id===edit.dataset.editNote);if(n){editingId=n.id;$('#note-text').value=n.text;$('#note-location').value=n.location;$('#note-cancel').hidden=false;$('#note-text').focus();}}},{signal});bindActions({modal,notify});$('#reader-state').addEventListener('change',e=>{const previous=paper.status;const updated={...paper,status:e.target.value,updatedAt:new Date().toISOString()};if(persist(updated,notify)){paper=updated;notify('阅读状态已更新。');}else e.target.value=previous;});$('#lit-note-form').addEventListener('submit',e=>{e.preventDefault();const text=$('#note-text').value.trim();if(!text)return;const now=new Date().toISOString(),old=paper.notes.find(n=>n.id===editingId),n={id:old?.id||crypto.randomUUID(),text,location:$('#note-location').value.trim(),createdAt:old?.createdAt||now,updatedAt:now};if(!old&&paper.notes.length>=100){notify('每篇文献最多 100 条笔记，请编辑已有笔记。');return;}const updated={...paper,notes:old?paper.notes.map(x=>x.id===n.id?n:x):[n,...paper.notes],updatedAt:now};if(persist(updated,notify)){paper=updated;editingId=null;$('#lit-note-form').reset();$('#note-cancel').hidden=true;$('#note-status').textContent='笔记已保存到当前浏览器。';renderNotes();document.querySelector('[data-read-tab="notes"]').textContent='我的笔记 '+paper.notes.length;}});$('#note-cancel').addEventListener('click',()=>{editingId=null;$('#lit-note-form').reset();$('#note-cancel').hidden=true;});$('#note-export').addEventListener('click',()=>{if(!paper.notes.length){notify('还没有笔记，请先记录并保存。');return;}download(paper.title+'-笔记.txt',[paper.title,...paper.notes.map(n=>`\n${n.location||'未填写定位'}\n${n.text}`)].join('\n'));notify('已发起笔记下载。');});}
function reviewComparison({modal,notify}){const rows=papers();modal('整理文献综述框架',`<p class="hub-description">选择文献，导出包含真实元数据与已有笔记的对照框架。研究方法和结论需自行核对填写，当前不会调用 AI。</p><form id="lit-compare-form" class="hub-form"><div class="lit-compare-list">${rows.map(p=>`<label><input type="checkbox" name="lit-compare" value="${esc(p.id)}"><span>${esc(p.title)}<small>${scopes[p.scope]} · ${esc(projectName(p.projectId))}</small></span></label>`).join('')||'<p>先添加文献，再整理综述。</p>'}</div><button class="btn primary" type="submit" ${rows.length?'':'disabled'}>导出对照框架 TXT</button><p id="compare-error" role="alert"></p></form>`);$('#lit-compare-form').addEventListener('submit',e=>{e.preventDefault();const ids=[...document.querySelectorAll('input[name="lit-compare"]:checked')].map(n=>n.value),selected=rows.filter(p=>ids.includes(p.id));if(!selected.length){$('#compare-error').textContent='请至少选择一篇文献。';return;}const text=['PaperKnow 文献对照框架','仅整理用户提供的元数据与笔记；未分析正文、未调用 AI。',...selected.map(p=>`\n标题：${p.title}\n作者：${p.authors||'未提供'}\n年份：${p.year||'未提供'}\n材料范围：${scopes[p.scope]}\nDOI：${p.doi||'未提供'}\nURL：${p.url||'未提供'}\n研究问题：[待核对填写]\n研究方法：[待核对填写]\n主要发现：[待核对填写]\n局限：[待核对填写]\n已有笔记：${p.notes.map(n=>n.text).join('；')||'暂无'}`)].join('\n');download('PaperKnow-文献对照框架.txt',text);notify('已发起对照框架下载。');});}

export function openLiteratureTranslation({modal,notify}){
 const rows=papers().filter(p=>p.scope!=='metadata'&&p.text?.trim());
 modal('翻译整理 · 文献与研读',`<p class="hub-description">选择已有原文，在同一文献的笔记中记录译文、术语与核对结果。不会自动翻译；AI 翻译尚未接入。</p><div class="more-translation-picker">${rows.map(p=>`<a href="${readerUrl(p)}?tab=notes"><b>${esc(p.title)}</b><small>${esc(scopes[p.scope])} · 打开原文与译文笔记 →</small></a>`).join('')||'<p class="hub-footnote">还没有可用原文。请导入有权使用的 DOCX / PDF / TXT，或手动添加原文。</p>'}</div><button class="btn primary" id="translation-import">添加原文材料</button>`);
 $('#translation-import').onclick=()=>paperForm(null,{modal,notify},true);
}
